from pathlib import Path
import json,html,csv
D=Path('work/sites/r15-ocala/dist'); data=json.loads(Path('work/research-ocala/investment-data.json').read_text()); S={x['id']:x for x in data['sources']}; P={x['id']:x for x in data['projects']}
e=lambda x:html.escape(str(x),quote=True)
def link(s,label=None):
 x=S[s];return f'<a href="{e(x["url"])}" target="_blank" rel="noopener">{e(label or x["title"])} <span aria-hidden="true">↗</span></a>'
def projects(ids,full=False):
 out=[]
 for i,k in enumerate(ids):
  x=P[k];cls=' project-full' if full else ''
  out.append(f'''<details class="investment-project{cls}" id="proyecto-{k}" data-project-category="{x['category']}"><summary><span class="project-no">{i+1:02}</span><span class="project-name"><small class="investment-status {x['statusClass']}">{e(x['status'])}</small><strong>{e(x['name'])}</strong><small>{e(x['date'])}</small></span><span class="project-amount">{e(x['metric'])}<small>{e(x['unit'])}</small></span><b class="project-toggle" aria-hidden="true">＋</b></summary><div class="project-content"><p class="project-location">{e(x['location'])}</p><div class="project-detail-grid"><div><h4>El proyecto</h4><p>{e(x['fact'])}</p></div><div><h4>Qué aporta a Ocala</h4><p>{e(x['meaning'])}</p></div></div><div class="project-scope"><h4>Estado y alcance</h4><p>{e(x['caveat'])}</p></div><div class="project-sources">{''.join(link(s) for s in x['sources'])}</div></div></details>''')
 return '\n'.join(out)
def gallery(prefix):
 return f'''<figure class="investment-gallery" data-investment-gallery><div class="investment-gallery-image"><img src="{prefix}assets/wec-propuesta-nocturna.jpg" alt="Render conceptual nocturno de los campos del proyecto deportivo del WEC, lámina 1 del expediente público" loading="lazy" width="1287" height="856"><span>RENDER CONCEPTUAL / EXPEDIENTE PÚBLICO</span><a href="{e(S['wec-renders']['url'])}" target="_blank" rel="noopener" aria-label="Abrir el documento original con 25 renders">Ver 25 láminas ↗</a></div><div class="gallery-controls" role="group" aria-label="Vistas del proyecto deportivo"><button data-gallery-src="{prefix}assets/wec-propuesta-nocturna.jpg" data-gallery-alt="Render conceptual nocturno de los campos del WEC, lámina 1" aria-pressed="true">01 · Vista nocturna</button><button data-gallery-src="{prefix}assets/wec-propuesta-diurna.jpg" data-gallery-alt="Render conceptual diurno del campus deportivo, lámina 16" aria-pressed="false">02 · El campus</button><button data-gallery-src="{prefix}assets/wec-propuesta-campos.jpg" data-gallery-alt="Render conceptual de campos y gradas, lámina 4" aria-pressed="false">03 · Campos y gradas</button></div><figcaption>Ilustraciones: Tillman &amp; Associates / MMTH. Láminas 1, 16 y 4 del expediente divulgado por Marion County. Muestran una propuesta, no el estado actual de las obras. {link('wec-renders','Consultar el original')}</figcaption></figure>'''
def stats():
 return f'''<div class="investment-signals"><article><span>INDUSTRIA / E-ONE</span><strong>US$23.5<span>M</span></strong><p>Ampliación industrial anunciada<br>100 empleos previstos</p>{link('eone','Comunicado de la empresa')}</article><article><span>INFRAESTRUCTURA / I-75 NORTE</span><strong>US$242<span>M</span></strong><p>Costo de construcción publicado<br>Finalización estimada: 2029</p>{link('i75n','Ficha oficial de FDOT')}</article><article><span>POBLACIÓN / MARION COUNTY</span><strong>+17.8<span>%</span></strong><p>Crecimiento de población<br>Abril de 2020 a julio de 2025</p>{link('census','Datos de U.S. Census')}</article></div>'''
def market():
 return f'''<div class="investment-market" id="mercado"><div><span class="eyebrow">EL MERCADO, CON PERSPECTIVA</span><h3>Una región con<br><em>trayectoria de crecimiento.</em></h3><p>El índice de vivienda de Ocala registra una apreciación acumulada del 48.14% en cinco años. Una referencia histórica para poner en perspectiva la evolución de la región, junto con los datos más recientes.</p>{link('fhfa','Consultar la tabla de FHFA')}</div><div><div class="market-figures"><div><small>5 AÑOS</small><strong>+48.14<span>%</span></strong></div><div><small>1 AÑO</small><strong>+2.18<span>%</span></strong></div><div><small>1 TRIMESTRE</small><strong>−0.38<span>%</span></strong></div></div><p class="market-method">FHFA · Ocala, FL MSA · 2026 T2 · All-Transactions, sin ajuste estacional. Índice histórico de precios de vivienda de la región. Los lotes se evalúan individualmente según ubicación, precio y costos de desarrollo.</p></div></div>'''
def filters():
 return '<div class="project-filters" role="group" aria-label="Filtrar proyectos">'+''.join(f'<button data-project-filter="{v}" aria-pressed="{str(v=="all").lower()}">{t}</button>' for v,t in [('all','Todos'),('wec','WEC y adquisiciones'),('empleo','Industria'),('infraestructura','Infraestructura'),('servicios','Salud')])+'</div>'
def library():
 return '<div class="source-library">'+''.join(f'<article class="source-item" data-source-search="{e((x["title"]+" "+x["publisher"]+" "+x["type"]).lower())}"><span>{i+1:02}</span><div><small>{e(x["publisher"])}</small>{link(x["id"])}<p>{e(x["type"])} · {e(x["date"])}</p></div></article>' for i,x in enumerate(data['sources']))+'</div><p id="source-empty" hidden role="status">No hay fuentes con esa búsqueda. Prueba con WEC, FDOT, Classic Mile o Census.</p>'
main=f'''<section class="investment chapter" id="inversion" data-label="Inversión y futuro">
<div class="investment-edition"><span class="eyebrow">03 / PERSPECTIVA DE INVERSIÓN</span><span>CUADERNO 01 <i></i> CORTE: 13 OCT 2026</span></div>
<div class="investment-intro"><h2>Ocala.<br><em>El próximo capítulo.</em></h2><div><p>Antes de elegir un lote,<br><strong>entiende lo que se mueve alrededor.</strong></p><p>Capital, infraestructura y nuevos destinos que dan contexto a una decisión de inversión. Explora los proyectos y consulta los documentos que los respaldan.</p><a class="investment-button" href="inversion/">Abrir dossier de inversión <span>↗</span></a></div></div>
{stats()}
<div class="investment-feature"><div class="investment-feature-copy"><span class="eyebrow">EN FOCO / WORLD EQUESTRIAN CENTER</span><h3>Una nueva escala<br><em>para el deporte.</em></h3><span class="investment-status planned">Aprobación urbanística con condiciones</span><p>Campos de competición, instalaciones interiores y espacios para espectadores forman parte del expediente deportivo de WEC.</p><p>El masterplan reúne deporte, espacios interiores y servicios para ampliar la actividad del destino. Explora las imágenes oficiales y los hitos del expediente.</p><div class="feature-docs">{link('wec-plan','Explorar el masterplan')}{link('wec-pud','Leer el expediente urbanístico')}</div><a class="investment-text-link" href="inversion/#proyecto-wec-deportivo">Explorar el proyecto y su documentación ↗</a></div>{gallery('inversion/')}</div>
<div class="investment-project-heading"><div><span class="eyebrow">DEL ANUNCIO AL DOCUMENTO</span><h3>Los movimientos<br><em>que conviene conocer.</em></h3></div><p>Abre cada proyecto para ver el monto o alcance, su estado y la fuente. Las compras de tierra y los presupuestos de obras se presentan por separado.</p></div>
<div class="investment-project-list">{projects(['classic-mile','sports-campos','eone','i75-norte','nw49','shoppes'])}</div>
<a class="investment-all" href="inversion/#proyectos">Ver los {len(data['projects'])} proyectos y adquisiciones <span>↗</span></a>
{market()}
<div class="investment-library-cta"><div><span class="eyebrow">TU MATERIAL DE APOYO</span><h3>La confianza empieza<br><em>con información.</em></h3><p>{len(data['sources'])} fuentes enlazadas: planos, renders, estudios técnicos, anuncios y estadísticas. Un dossier para leer, imprimir y conversar con tu equipo.</p></div><a class="investment-document" href="inversion/#documentos"><span>RAINBOW PARK<br>COLLECTION</span><b>Dossier<br>Ocala 2026</b><small>PROYECTOS + DATOS + DOCUMENTOS</small><span class="document-arrow">↗</span></a></div>
<p class="investment-disclosure">Proyectos de terceros, presentados como contexto regional. Fechas y alcances según las fuentes enlazadas. La evaluación de cada lote considera su ubicación, precio, costos y condiciones del mercado. Rainbow Park Collection es independiente del WEC.</p>
</section>'''
intro=f'''<header class="dossier-header"><a href="../#inversion" class="dossier-brand">Rainbow Park <em>Collection</em><small>BY NEXT FRAGA</small></a><a href="../#inversion">← Volver al proyecto</a><button data-print-dossier>Imprimir / guardar PDF ↓</button></header><main class="dossier-main"><div class="investment-edition"><span class="eyebrow">DOSSIER DE INVERSIÓN / OCALA, FLORIDA</span><span>EDICIÓN 01 · 13 OCTUBRE 2026</span></div><div class="dossier-intro"><div><h1>El territorio.<br><em>La evidencia.<br>Tu decisión.</em></h1><p>Una lectura documentada de los proyectos, las adquisiciones y los cambios económicos que rodean a Ocala. Preparada para quienes evalúan invertir desde cualquier parte del mundo.</p></div><div class="dossier-summary"><b>{len(data['projects']):02}</b><span>proyectos y adquisiciones</span><b>{len(data['sources']):02}</b><span>fuentes para consultar</span><small>Corte editorial: 13 de octubre de 2026.<br>USD · superficies en acres o ft² según la fuente.</small></div></div><nav class="dossier-index" aria-label="Contenido del dossier"><a href="#tesis">01 · La oportunidad</a><a href="#proyectos">02 · Los proyectos</a><a href="#datos">03 · Los datos</a><a href="#documentos">04 · Los documentos</a><a href="#decision">05 · Tu decisión</a></nav>'''
body=f'''<section id="tesis" class="dossier-section"><div class="investment-project-heading"><div><span class="eyebrow">01 / LA OPORTUNIDAD</span><h2>Un entorno con<br><em>varios motores.</em></h2></div><p>Industria, infraestructura, servicios y actividad ecuestre aportan fundamentos para estudiar la zona. La oportunidad concreta se determina al comparar precio de compra, costos y demanda de cada propiedad.</p></div>{stats()}<div class="thesis-grid"><article><span>01</span><h3>Empleo y residentes</h3><p>El crecimiento de población y la ampliación de empresas suman residentes, empleos y necesidades de vivienda a la región.</p></article><article><span>02</span><h3>Accesos y servicios</h3><p>La inversión en carreteras y atención médica refuerza la conectividad y los servicios que buscan quienes eligen establecerse en Ocala.</p></article><article><span>03</span><h3>Un destino con actividad</h3><p>Deporte, hoteles, comercio y eventos amplían las razones para visitar Ocala y desarrollar servicios vinculados a su actividad durante el año.</p></article></div></section>
<section id="proyectos" class="dossier-section"><div class="investment-project-heading"><div><span class="eyebrow">02 / PROYECTOS Y ADQUISICIONES</span><h2>El capital se mueve.<br><em>El territorio evoluciona.</em></h2></div><p>“Anunciado” refleja una intención del promotor; “aprobado” describe un hito urbanístico; “en construcción” requiere evidencia de obra; “inaugurado” corresponde a una entrega comunicada.</p></div>{gallery('')}<div class="sports-program"><span class="eyebrow">PROGRAMA DEL PLAN DIVULGADO POR EL CONDADO</span><p>8 campos sintéticos multiuso · 3 de césped natural · 6 de béisbol/softbol · 1 campo de campeonato · recinto interior con 2 pistas de hielo, 8 canchas de baloncesto convertibles en 16 de voleibol y fútbol interior · 2 restaurantes.</p><small>Componentes propuestos del expediente; no instalaciones terminadas. El anuncio de primera fase de 11 campos tiene otro alcance y no se suma a este programa.</small>{link('wec-county','Ver programa y documentos del condado')}</div>{filters()}<p id="project-count" class="filter-count" role="status">{len(P)} proyectos y adquisiciones</p>{projects(list(P),True)}<div class="dossier-timeline"><span class="eyebrow">HORIZONTES PUBLICADOS / SUJETOS A CAMBIO</span><div><article><b>2026</b><p>Shoppes y primera fase Sports at WEC: previsiones del promotor.</p></article><article><b>2027</b><p>E-ONE: finalización prevista en primavera.</p></article><article><b>2028</b><p>Enlace I-75 / NW 49th: finalización estimada en otoño.</p></article><article><b>2029</b><p>I-75 norte y sur: finalización estimada a principios de año.</p></article></div><small>Las fuentes y condiciones figuran en cada ficha. No son fechas de entrega de viviendas de Rainbow Park Collection.</small></div></section>
<section id="datos" class="dossier-section"><span class="eyebrow">03 / DATOS PARA PONERLO EN PERSPECTIVA</span>{market()}<div class="data-grid"><article><small>MARION COUNTY / JUL 2025</small><b>442,660</b><h3>habitantes estimados</h3><p>+17.8% desde abril de 2020. El condado también registra 5,985 permisos de construcción en 2025: crece la población y también la oferta.</p>{link('census','Census QuickFacts')}</article><article><small>OCALA MSA / AGO 2026 · PRELIMINAR</small><b>126,700</b><h3>empleos no agrícolas</h3><p>+1.2% interanual. Manufactura: +6.1%; educación y salud: +2.8%. Desempleo: 5.7%, sin ajuste estacional.</p>{link('bls','Bureau of Labor Statistics')}</article><article><small>MARION COUNTY / TURISMO FY2025</small><b>US$956.45M</b><h3>impacto económico estimado</h3><p>−0.8% anual. El informe registra 1.33 millones de visitantes (−7.3%) y 1.17 millones de noches pagadas (+5.6%). Los indicadores evolucionan de forma diferente.</p>{link('tourism','Informe oficial de turismo')}</article><article><small>CEP / BALANCE DE MITAD DE 2026</small><b>US$417M</b><h3>cartera potencial comunicada</h3><p>La publicación institucional distingue US$70M de inversión reportada y 549 empleos nuevos, de una cartera potencial de US$417M / 1,669 empleos. No es capital comprometido.</p>{link('cep','Publicación institucional del CEP')}<p class="data-note">El informe completo no pudo verificarse; se conserva como contexto, fuera de los importes principales. Puede incluir proyectos ya citados.</p></article></div></section>
<section id="documentos" class="dossier-section"><div class="investment-project-heading"><div><span class="eyebrow">04 / BIBLIOTECA DOCUMENTAL</span><h2>Ve directamente<br><em>a la fuente.</em></h2></div><p>Los enlaces abren documentos y páginas de sus publicadores. Los escritos judiciales contienen alegaciones de las partes; no son sentencias. Las noticias están identificadas como prensa.</p></div><div class="source-tools"><label for="source-search">Buscar en las {len(S)} fuentes<input id="source-search" type="search" placeholder="WEC, Classic Mile, FDOT, población…"></label><a href="fuentes-ocala.csv" download>Descargar índice de fuentes · CSV ↓</a></div>{library()}</section>
<section id="decision" class="dossier-section decision-section"><span class="eyebrow">05 / DEL ENTORNO A TU PROPIEDAD</span><h2>El siguiente paso:<br><em>los números de tu lote.</em></h2><p>Para un inversionista que está fuera del país, la claridad empieza por una propiedad identificada y una operación que pueda revisar a distancia.</p><div class="decision-grid"><article><span>01 / EL ACTIVO</span><h3>Identificar y comprobar</h3><p>Número de parcela, titularidad, levantamiento, acceso legal, uso permitido, retiros, drenaje y servicios disponibles.</p></article><article><span>02 / LA EJECUCIÓN</span><h3>Definir cuánto cuesta</h3><p>Compra, cierre, preparación del terreno, conexión de servicios, construcción, permisos, seguros, financiación y contingencia.</p></article><article><span>03 / EL RESULTADO</span><h3>Evaluar escenarios</h3><p>Comparables recientes, precio de salida, plazo de venta, gastos de mantenimiento y, si aplica, renta neta, vacancia y gestión.</p></article></div><div class="decision-cta"><a class="investment-button" href="../#contacto">Preparar mi consulta con Next Fraga <span>↗</span></a><a href="../#lotes">Explorar el territorio →</a></div><p class="investment-disclosure">Material informativo, con corte al 13 de octubre de 2026. Fechas sujetas a actualización. Las estadísticas describen el mercado regional y los resultados históricos no garantizan rendimientos futuros. Rainbow Park Collection no está afiliada a WEC ni a los demás promotores citados.</p></section></main><footer class="dossier-footer"><span>RAINBOW PARK COLLECTION · BY NEXT FRAGA</span><a href="../#inversion">Volver al proyecto ↑</a></footer>'''
page=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#172e29"><title>Ocala: proyectos y evidencia | Rainbow Park Collection</title><meta name="description" content="Dossier de Ocala: WEC, Classic Mile, E-ONE, infraestructura, salud y datos de mercado con fuentes y documentos públicos."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Italiana&display=swap" rel="stylesheet"><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="../investment.css?v=1"></head><body class="dossier-body"><a class="skip" href="#proyectos">Saltar a los proyectos</a>{intro}{body}<script src="../investment.js?v=1" defer></script></body></html>'''
(D/'inversion/index.html').write_text(page)
(D/'inversion/evidencia-ocala.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
with (D/'inversion/fuentes-ocala.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f);w.writerow(['Fuente','Publicador','Tipo','Fecha','Enlace','Corte de revisión']);w.writerows([[x['title'],x['publisher'],x['type'],x['date'],x['url'],data['asOf']] for x in data['sources']])
p=D/'index.html';s=p.read_text()
existing=s.find('<section class="investment chapter"'); boundary=s.find('<section class="collection chapter collection-legacy"',existing)
if existing>=0 and boundary>=0:s=s[:existing]+s[boundary:]
start=s.index('<div id="actualidad"');end=s.index('</section>',start)
s=s[:start]+'''<div id="actualidad" class="territory-to-collection"><p>Conoce lo que está cambiando.<br><em>Descubre el próximo capítulo de Ocala.</em></p><a href="#inversion">Proyectos y evidencia <span>↘</span></a></div>\n'''+s[end:]
s=s.replace('<section class="collection chapter collection-legacy"',main+'\n<section class="collection chapter collection-legacy"',1)
s=s.replace('<link rel="stylesheet" href="immersive.css?v=20261013d">','<link rel="stylesheet" href="immersive.css?v=20261013d"><link rel="stylesheet" href="investment.css?v=1">')
s=s.replace('<a href="#viviendas" data-section="viviendas"><span>03</span> Viviendas</a>','<a href="#inversion" data-section="inversion"><span>03</span> Inversión</a><a href="#viviendas" data-section="viviendas"><span>04</span> Viviendas</a>')
s=s.replace('<span>04</span> Conversemos','<span>05</span> Contacto')
s=s.replace('<a href="#viviendas"><small>03</small>','<a href="#inversion"><small>03</small><span>Invertir en Ocala<em>Proyectos, datos y documentos</em></span><b>↗</b></a><a href="#viviendas"><small>04</small>')
s=s.replace('<a href="#contacto"><small>04</small>','<a href="#contacto"><small>05</small>')
s=s.replace('03 / ESTUDIO DE VIVIENDAS','04 / ESTUDIO DE VIVIENDAS').replace('04 / COMIENZA UNA CONVERSACIÓN','05 / COMIENZA UNA CONVERSACIÓN')

if 'src="investment.js?' not in s:s=s.replace('</body>','<script src="investment.js?v=1" defer></script></body>')
p.write_text(s)
print('Created investment section, dossier, source CSV and evidence JSON.',len(P),'projects;',len(S),'sources.')
